import AppIntents
import WidgetKit

// Configuration shown in "Edit Widget". Shared by the macOS and iOS widgets.
//
// !! macOS: Xcode is not used to build the macOS app, so the App Intents metadata that the system reads
// !! (ClockWidgets.appex/Contents/Resources/Metadata.appintents) is generated by
// !! macOS/scripts/gen_appintents_metadata.py from a hand-maintained description of the types below.
// !! When you add/rename/remove an intent, a parameter or an options provider here, update SPEC in that
// !! script too (the build fails if the two disagree — see macOS/docs/ARCHITECTURE.md §5).
// !! iOS: Xcode generates the metadata from this file, so there is nothing to keep in sync.
//
// !! Every parameter is a Bool or a String. Not an AppEnum or AppEntity: to decode those, the AppIntents
// !! runtime in the extension asks linkd for the app's metadata, and linkd only answers processes signed with
// !! a Team ID ("Rejecting invalid client due to requiresValidatedBundle"). In an ad-hoc signed build every
// !! enum or entity value came back empty and the widget silently fell back to its defaults. Strings and
// !! Bools need no metadata. The option lists come from DynamicOptionsProviders, and each value is the text
// !! the user sees (Shared/Core/WidgetOptions.swift).

// MARK: - Option lists

/// Style: Analog, Digital.
struct StyleOptionsProvider: DynamicOptionsProvider {
    func results() async throws -> [String] {
        ClockStyle.optionValues
    }
}

/// Time Format: System Setting, 12-Hour, 24-Hour.
struct TimeFormatOptionsProvider: DynamicOptionsProvider {
    func results() async throws -> [String] {
        HourCycle.optionValues
    }
}

/// City / Cities: the cities in the app's World Clock list first, then all 582 cities of Apple's Clock app,
/// A to Z. Each value is "Name, Country" (unique in Apple's list).
struct CityOptionsProvider: DynamicOptionsProvider {
    func results() async throws -> IntentItemCollection<String> {
        let database = CityDatabase.shared
        let list = DefaultCities.worldClockList(database: database)
        let suggested = DefaultCities.filled(list, to: list.count + DefaultCities.fillerIDs.count, database: database)
        let all = database.cities.sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
        return IntentItemCollection(sections: [
            IntentItemSection("Suggested", items: suggested.map(Self.item)),
            IntentItemSection("All Cities", items: all.map(Self.item)),
        ])
    }

    private static func item(_ city: City) -> IntentItem<String> {
        IntentItem(city.optionValue, title: "\(city.optionValue)")
    }
}

// MARK: - Configuration intents
//
// Cities: Edit Widget shows one row per clock (4, 4, 8 and 12 for the small, medium, large and extra-large
// sizes), like Apple's World Clock widget. Those row counts are in the metadata only (SPEC's WORLD_CLOCK_ROWS,
// checked against ClockFamily.worldClockCapacity): for a [String] parameter, @Parameter can't take both `size:`
// and `optionsProvider:`, and the system reads the sizes from the metadata, not from Swift. On iOS, Xcode generates
// the metadata without them, and the app target's "Add Cities rows" build phase (iOS/scripts/add_city_rows.sh)
// adds them to the embedded widget extension.

/// What every clock widget's configuration provides.
protocol ClockConfigurationIntent: WidgetConfigurationIntent {
    /// The style when the saved value is missing or unreadable.
    static var defaultStyle: ClockStyle { get }
    var styleValue: String { get }
    var showsSecondsValue: Bool { get }
    var timeFormatValue: String { get }
    /// Cities picked in Edit Widget (empty = use the app's list / the City Widget city).
    var cityValues: [String] { get }
}

extension ClockConfigurationIntent {
    var clockStyle: ClockStyle { ClockStyle(optionValue: styleValue) ?? Self.defaultStyle }
    var hourCycle: HourCycle { HourCycle(optionValue: timeFormatValue) ?? .system }
    /// The picked cities that resolve. A value that doesn't (renamed by a later city list) is skipped.
    var chosenCities: [City] { cityValues.compactMap { CityDatabase.shared.city(optionValue: $0) } }
}

struct CityAnalogIntent: ClockConfigurationIntent {
    static var title: LocalizedStringResource = "City"
    static var description = IntentDescription("Check the time in a city of your choice.")
    static let defaultStyle = ClockStyle.analog

    @Parameter(title: "City", description: "Leave empty to use the City Widget city set in the Digital World-Clock Widgets app (normally the city of your time zone).", optionsProvider: CityOptionsProvider())
    var city: String?

    @Parameter(title: "Style", default: "Analog", optionsProvider: StyleOptionsProvider())
    var style: String

    @Parameter(title: "Show Seconds", description: "Digital clocks show the seconds under the time. Analog hands move once a minute.", default: true)
    var showsSeconds: Bool

    @Parameter(title: "Time Format", description: "Used by the digital style.", default: "System Setting", optionsProvider: TimeFormatOptionsProvider())
    var timeFormat: String

    init() {}

    var styleValue: String { style }
    var showsSecondsValue: Bool { showsSeconds }
    var timeFormatValue: String { timeFormat }
    var cityValues: [String] { city.map { [$0] } ?? [] }
}

